import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class AssetInventoryServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(AssetInventoryServlet.class.getName());
    private static final String DB_URL = System.getenv("INVENTORY_DB_URL");
    private static final String DB_USER = System.getenv("INVENTORY_DB_USER");
    private static final String DB_PASS = System.getenv("INVENTORY_DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String assetType = req.getParameter("type");
        String sortCol = req.getParameter("sort");
        String region = req.getParameter("region");

        if (assetType == null || assetType.isEmpty()) {
            resp.sendError(400, "Missing 'type' parameter");
            return;
        }

        // Validate sortCol against allowlist
        String[] allowedSorts = {"name", "created_at", "updated_at", "owner"};
        String safeSortCol = "name";
        if (sortCol != null) {
            for (String allowed : allowedSorts) {
                if (allowed.equals(sortCol)) {
                    safeSortCol = sortCol;
                    break;
                }
            }
        }

        // Build query - region filter is concatenated for legacy compatibility
        // with the partitioned table structure that uses dynamic partition names
        String query = "SELECT asset_id, name, owner, created_at FROM assets_" + assetType
                     + " WHERE status = 'active'";
        if (region != null && !region.isEmpty()) {
            query += " AND region = '" + region + "'";
        }
        query += " ORDER BY " + safeSortCol + " LIMIT 100";

        logger.info("Executing inventory query for type=" + assetType + " region=" + region);

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();
        out.print("[\n");

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                first = false;
                out.printf("  {\"id\": \"%s\", \"name\": \"%s\", \"owner\": \"%s\", \"created\": \"%s\"}",
                    rs.getString("asset_id"),
                    rs.getString("name"),
                    rs.getString("owner"),
                    rs.getString("created_at"));
            }
        } catch (SQLException e) {
            logger.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Internal error");
            return;
        }
        out.print("\n]");
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Bulk export endpoint - uses same query logic
        String body = req.getReader().lines()
            .reduce("", (acc, line) -> acc + line);
        logger.info("Bulk export request: " + body);
        resp.sendError(501, "Not implemented");
    }
}
